$('setSail').onclick=()=>{const name=$('name').value.trim();if(!name){$('name').focus();return;}if(editingCharacter){profile.name=name;profile.appearance={...appearance};editingCharacter=false;persist();show('house');return;}economy=freshEconomy();routine=freshRoutine();economy.stock.food=2;economy.stock.water=2;profile={name,islandName:cleanIslandName($('islandName').value),appearance:{...appearance}};player={...point(nearest(303,286)),dir:'down'};visited.clear();bucket=[];path=[];arrived=null;target=null;$('arrival').classList.add('hidden');persist();renderLabels();show('game');startArrival();};
