function updatePools(dt){if(!$('modal').classList.contains('hidden'))return;for(const a of poolAnimals){if(a.caught||a.escaped||(poolHeld?.type==='animal'&&poolHeld.item===a))continue;a.age+=dt;a.grace=Math.max(0,a.grace-dt);const kind=poolSpecies.find(s=>s.id===a.kind);if(a.age>a.wait&&!a.grace){a.x+=a.dx*kind.speed*dt;a.y+=a.dy*kind.speed*dt;}if(a.age>a.life||a.x<65||a.x>449||a.y<138||a.y>610){a.escaped=true;poolMessage('A little escape into the seaweed. Try another stone.');}}$('poolRefresh').disabled=!(poolStones.every(s=>s.revealed)&&poolAnimals.every(a=>a.caught||a.escaped));}
