function valueOfFish(c){return c.spoiled?0:Math.max(1,Math.round(c.size*(c.species==='mackerel'?.45:.6)));}
function creatureValue(c){return c.spoiled?0:Math.round(c.size*(c.species==='octopus'?1.4:2));}
function sellFish(species=null){if(!boatState('trader').active)return false;let value=0;bucket=bucket.filter(c=>{if(!c.spoiled&&(!species||c.species===species)){value+=valueOfFish(c);return false;}return true;});routine.creatures=routine.creatures.filter(c=>{if(!c.spoiled&&(!species||c.species===species)){value+=creatureValue(c);return false;}return true;});if(!value)return false;economy.coins+=value;persist();updateBoatBoard();openTrader(`Sold your fresh catches for ${value} coins.`);return true;}
function openTrader(message=''){if(!boatState('trader').active){modal('The trader is at sea','<p>Check the boat icon for the next Wednesday morning visit.</p>');return;}const fresh=bucket.filter(c=>!c.spoiled),freshPool=routine.creatures.filter(c=>!c.spoiled),total=fresh.reduce((n,c)=>n+valueOfFish(c),0)+freshPool.reduce((n,c)=>n+creatureValue(c),0);modal('A fair trade',`${message?`<p class="trade-message">${message}</p>`:''}<p><b>${economy.coins} coins</b></p><button class="action gold" id="sell-all" ${!total?'disabled':''}>Sell all fresh catches · ${total} coins</button>${fishSpecies.concat(poolSpecies).map(f=>{const group=fresh.concat(freshPool).filter(c=>c.species===f.id);return group.length?`<button class="action" id="sell-${f.id}">Sell ${group.length} ${f.name.toLowerCase()}</button>`:'';}).join('')}<p class="mini-note">Spoiled catches cannot be sold. Your collection records remain after selling.</p><h3>Fishing supplies</h3>${saleRows(traderItems,'trader')}`,'THE TRADER');$('sell-all').onclick=()=>sellFish();for(const f of fishSpecies.concat(poolSpecies))if(fresh.concat(freshPool).some(c=>c.species===f.id))$('sell-'+f.id).onclick=()=>sellFish(f.id);wirePurchases(traderItems,'trader');}
function showBucket(){modal('Your fishing bucket',bucket.length?bucket.slice().reverse().map(c=>`<div class="journal-row">${fishSpecies.find(f=>f.id===c.species).name}<span>${c.spoiled?'Spoiled':c.size.toFixed(1)+' cm'}</span></div>`).join(''):'<p>Your fish bucket is empty.</p>','YOUR CATCHES');}
