const loadRoutineV5=loadRoutine;loadRoutine=function(data){loadRoutineV5(data);routine.introPending=data?.introPending===true;routine.chest={items:{},fish:[],creatures:[]};for(const k of supplyKeys){const n=data?.chest?.items?.[k];if(Number.isSafeInteger(n)&&n>0&&n<=100000)routine.chest.items[k]=n;}routine.chest.fish=Array.isArray(data?.chest?.fish)?data.chest.fish.filter(validCatch):[];routine.chest.creatures=Array.isArray(data?.chest?.creatures)?data.chest.creatures.filter(c=>poolSpecies.some(p=>p.id===c.species)&&Number.isFinite(c.size)&&c.size>0&&c.size<100&&typeof c.caughtAt==='string'):[];intro=null;resetMotions();};
