function scheduledBoat(id){const s=boatServices.find(s=>s.id===id),c=calendar(),start=480,end=720;if(c.weekday===s.weekday&&c.minute>=start&&c.minute<end)return {scheduled:true,in:0,left:end-c.minute};let ahead=(s.weekday-c.weekday+7)%7;if(!ahead&&c.minute>=end)ahead=7;return {scheduled:false,in:ahead*DAY+start-c.minute,left:0};}
