function startArrival(){resetMotions();intro={stage:'sailing',elapsed:0,boat:0,line:0};routine.introPending=true;player={x:84,y:351,dir:'right'};path=[];arrived=null;target=null;walking=false;$('arrival').classList.add('hidden');$('app').classList.add('arrival-playing');$('welcomeScene').classList.remove('hidden');$('welcomeDialogue').classList.add('hidden');$('welcomeCaption').textContent='Home, at last.';persist();}
