function openChest(message=''){const contents=(stock,fromChest)=>supplyKeys.filter(k=>stock[k]>0).map(k=>`<div class="storage-item">${foodIcon(k)}<b>${itemNames[k]} <small>×${stock[k]}</small></b><div><button id="${fromChest?'take':'store'}-${k}">${fromChest?'Take':'Store'} one</button><button id="${fromChest?'takeall':'storeall'}-${k}">Stack</button></div></div>`).join('')||'<p class="mini-note">Nothing here yet.</p>';modal('Your wooden storage chest',`${packCounter()}${message?`<p class="trade-message">${message}</p>`:''}<div class="storage-tabs"><button id="storagePack">From backpack</button><button id="storageBox">From chest</button></div><div id="storageItems"></div><p class="mini-note">The chest has plenty of room. Keep food in the fridge for refrigeration. Clothing stays available in your wardrobe.</p>`,'TUCKED AWAY');function render(fromChest){$('storageItems').innerHTML=contents(fromChest?routine.chest.items:economy.stock,fromChest)+['fish','creatures'].map(kind=>{const n=(fromChest?routine.chest[kind]:kind==='fish'?bucket:routine.creatures).length;return n?`<div class="storage-catches"><b>${kind==='fish'?'Fish':'Rock-pool catches'} · ${n}</b><button id="move-${kind}">${fromChest?'Take':'Store'} one</button><button id="all-${kind}">All</button></div>`:'';}).join('');for(const k of supplyKeys)if((fromChest?routine.chest.items:economy.stock)[k]>0)for(const all of [false,true])$(`${fromChest?(all?'takeall':'take'):(all?'storeall':'store')}-${k}`).onclick=()=>{const ok=transferSupply(k,fromChest,all);openChest(ok?'Moved safely.':'No room in your backpack.');render(fromChest);};for(const kind of ['fish','creatures'])if($( 'move-'+kind)){ $('move-'+kind).onclick=()=>{transferCatches(kind,fromChest);openChest('Moved safely.');render(fromChest);};$('all-'+kind).onclick=()=>{transferCatches(kind,fromChest,true);openChest('Moved safely.');render(fromChest);};}}$('storagePack').onclick=()=>render(false);$('storageBox').onclick=()=>render(true);render(false);}
