// v0.7 — letters, parcels and a few island companions.
const requestKinds={fish:{title:'A fish for supper',from:'Mara, across the sound',need:'One mackerel measuring at least 25 cm',coins:35,decor:'shell'},crab:{title:'A tiny tide-pool visitor',from:'The island nature club',need:'One hermit crab, any size',coins:45},lost:{title:'My missing brass key',from:'Ellis, ferry crew',need:'A lost brass key last seen on the beach',coins:55,decor:'plant'}};
const beachTypes={shell:{name:'Scallop shell',metal:false,value:3},glass:{name:'Sea glass',metal:false,value:4},wood:{name:'Driftwood',metal:false,value:2},pebble:{name:'Smooth pebble',metal:false,value:1},coin:{name:'Old coin',metal:true,value:6},cap:{name:'Bottle cap',metal:true,value:1},key:{name:'Lost brass key',metal:true,value:0}};
function freshPost(){return {letters:[],requests:[],serial:0,lastFerry:-1,started:false};}
function initV7(){routine.post||=freshPost();routine.beachBucket||=[];routine.beachRecords||={};routine.chest.beach||=[];routine.decor||={plant:false,rug:false,shell:false};}
const freshRoutineV6=freshRoutine;freshRoutine=function(){const r=freshRoutineV6();r.post=freshPost();r.beachBucket=[];r.beachRecords={};r.chest.beach=[];r.decor={plant:false,rug:false,shell:false};return r;};
function validBeach(c){return c&&beachTypes[c.type]&&typeof c.foundAt==='string';}
const loadRoutineV6=loadRoutine;loadRoutine=function(d){loadRoutineV6(d);initV7();const p=d?.post;if(p&&typeof p==='object'){routine.post.serial=Number.isSafeInteger(p.serial)&&p.serial>=0?p.serial:0;routine.post.lastFerry=Number.isInteger(p.lastFerry)?p.lastFerry:-1;routine.post.started=p.started===true;routine.post.requests=Array.isArray(p.requests)?p.requests.filter(r=>r&&requestKinds[r.kind]&&/^req-\d+$/.test(r.id)&&['finding','ready','shipped','replied','complete','missed'].includes(r.status)&&Number.isFinite(r.deadline)).slice(-80).map(r=>({...r,parcel:r.parcel&&((r.kind==='fish'&&validCatch(r.parcel))||(r.kind==='crab'&&r.parcel.species==='hermit'&&Number.isFinite(r.parcel.size))||(r.kind==='lost'&&validBeach(r.parcel)))?r.parcel:null})):[];routine.post.letters=Array.isArray(p.letters)?p.letters.filter(l=>l&&typeof l.id==='string'&&/^(bulletin-storm|(request|thanks)-req-\d+)$/.test(l.id)&&['bulletin','request','thanks'].includes(l.kind)).slice(-100).map(l=>({id:l.id,kind:l.kind,requestId:l.requestId,read:l.read===true,claimed:l.claimed===true})):[];}for(const r of routine.post.requests){if(r.status==='ready'&&(!r.parcel||!Number.isFinite(r.pickupAt))){r.status='finding';r.parcel=null;}if(r.status==='shipped'&&!Number.isFinite(r.returnAt)){r.returnAt=nextCollection()+7*DAY-240;}}routine.beachBucket=Array.isArray(d?.beachBucket)?d.beachBucket.filter(validBeach):[];routine.chest.beach=Array.isArray(d?.chest?.beach)?d.chest.beach.filter(validBeach):[];for(const k of Object.keys(beachTypes))routine.beachRecords[k]=Number.isSafeInteger(d?.beachRecords?.[k])?Math.max(0,d.beachRecords[k]):0;for(const k of ['plant','rug','shell'])routine.decor[k]=d?.decor?.[k]===true;routine.beachPatch=validPatch(d?.beachPatch)?d.beachPatch:null;if(!routine.post.started&&!routine.introPending)startPost();};
const loadV6=load;load=function(d){loadV6(d);for(const k of ['plant','rug','shell'])economy.owned[k]=d.economy?.owned?.[k]===true||routine.decor[k]||(economy.stock[k]||0)>0||(routine.chest.items[k]||0)>0;};
function dayLabel(day){const c=calendar(day*DAY+480);return `${c.short} ${c.date.getUTCDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][c.date.getUTCMonth()]}`;}
function nextCollection(min=absoluteMinute()){const c=calendar(min);let ahead=(1-c.weekday+7)%7;if(!ahead&&c.minute>=720)ahead=7;return (c.day+ahead)*DAY+720;}
function addLetter(kind,requestId=''){const id=kind+'-'+(requestId||'storm');if(!routine.post.letters.some(l=>l.id===id))routine.post.letters.push({id,kind,requestId,read:false,claimed:false});}
function issueRequest(kind){if(routine.post.requests.filter(r=>['finding','ready','shipped'].includes(r.status)).length>=2)return null;const id='req-'+(++routine.post.serial),deadline=nextCollection()+7*DAY;const r={id,kind,status:'finding',deadline,parcel:null,pickupAt:0,returnAt:0};routine.post.requests.push(r);addLetter('request',id);return r;}
