const invValid10=inventoryValid;inventoryValid=function(e,to){if(!e||e.source===to)return false;if(['fridge','freezer'].includes(to)){if(e.ref?.spoiled)return false;if(e.kind==='stock')return !!foodTypes[e.key]&&coldRoom(to,e.key)>0;return edibleCatch(e)&&coldUsed(to)<(to==='fridge'?24:COLD_SLOTS);}if(to==='chest'&&['fish','creature'].includes(e.kind))return false;if(to==='parcel'){const r=routine.post.requests.find(r=>r.id===deliveryRequest);return r?.status==='finding'&&!!e.ref&&suitable(r,e.ref)&&inventoryArray(e.source,e.kind).includes(e.ref);}return invValid10(e,to);};
inventoryMove=function(e,to,all=false){if(!inventoryValid(e,to))return false;if(e.source==='parcel')return retrieveParcel(deliveryRequest);if(to==='parcel')return false;if(e.kind==='stock'){const from=inventoryStock(e.source),dest=inventoryStock(to);let n=Math.min(from[e.key]||0,all?e.count:1);if(to==='pack')n=Math.min(n,20-(dest[e.key]||0));if(['fridge','freezer'].includes(to))n=Math.min(n,coldRoom(to,e.key));if(n<=0)return false;from[e.key]-=n;dest[e.key]=(dest[e.key]||0)+n;}else{const from=inventoryArray(e.source,e.kind),dest=inventoryArray(to,e.kind),i=from.indexOf(e.ref);if(i<0)return false;dest.push(from.splice(i,1)[0]);}persist();playFX('drop');updateChecklist(true);return true;};
