 const select=e=>{inventorySelected=e;document.querySelectorAll('.inventory-tile').forEach(b=>b.classList.toggle('selected',entries[Number(b.dataset.entry)]===e));$('inventoryDetail').innerHTML=`${inventoryArt(e)}<b>${inventoryName(e)}${e.ref?.spoiled?' · spoiled':''}</b>${e.kind==='stock'&&foodTypes[e.key]&&e.source!=='chest'?'<button id="inventoryEat" aria-label="Eat or drink now">'+uiIcon('eat')+'</button>':''}${['fish','creature'].includes(e.kind)&&!e.ref?.spoiled?'<button id="releaseCatch">Put back</button>':''}${e.ref?.spoiled?'<button id="inventoryDiscard" aria-label="Discard spoiled item">'+uiIcon('trash')+'</button>':''}`;if($('releaseCatch'))$('releaseCatch').onclick=()=>{modal('Put this catch back?',inventoryArt(e)+'<p>'+htmlText(inventoryName(e))+'</p><button id="confirmRelease" class="action gold">Release</button><button id="keepCatch" class="action">Keep</button>');$('confirmRelease').onclick=()=>{releaseCatch(e);openInventory(mode);};$('keepCatch').onclick=()=>openInventory(mode);};if($('inventoryEat'))$('inventoryEat').onclick=()=>{consume(e.key,e.source);openInventory(mode);};if($('inventoryDiscard'))$('inventoryDiscard').onclick=()=>{const a=inventoryArray(e.source,e.kind),i=a.indexOf(e.ref);if(i>=0)a.splice(i,1);persist();openInventory(mode);};};
 document.querySelectorAll('[data-entry]').forEach(b=>{const e=entries[Number(b.dataset.entry)];b.onclick=()=>select(e);b.onpointerdown=p=>{if(p.button&&p.button!==0)return;inventoryDrag={entry:e,x:p.clientX,y:p.clientY,active:false,node:b,pointer:p.pointerId};b.setPointerCapture?.(p.pointerId);};b.onpointermove=p=>{const d=inventoryDrag;if(!d||d.node!==b)return;if(!d.active&&Math.hypot(p.clientX-d.x,p.clientY-d.y)>9){d.active=true;d.ghost=document.createElement('div');d.ghost.className='inventory-ghost';d.ghost.innerHTML=inventoryArt(e);document.body.append(d.ghost);}if(d.active){p.preventDefault();d.ghost.style.left=p.clientX+'px';d.ghost.style.top=p.clientY+'px';document.querySelectorAll('[data-inventory-container]').forEach(c=>c.classList.toggle('drop-ready',inventoryValid(e,c.dataset.inventoryContainer)));}};b.onpointerup=p=>{const d=inventoryDrag;if(!d||d.node!==b)return;if(d.active){const dest=document.elementFromPoint(p.clientX,p.clientY)?.closest('[data-inventory-container]')?.dataset.inventoryContainer;cleanInventoryDrag();if(dest&&dest!==e.source)requestInventoryMove(e,dest);p.preventDefault();}else cleanInventoryDrag();};b.onpointercancel=cleanInventoryDrag;});
