const consume10=consume;consume=function(key,source='pack'){if(source!=='freezer')return consume10(key,source);const item=foodTypes[key],stock=inventoryStock(source);if(!item||!stock[key])return false;stock[key]--;routine.food=Math.min(100,routine.food+item.food);routine.water=Math.min(100,routine.water+item.water);persist();updateLifeUI();return true;};
requestInventoryMove=function(e,to){if(!inventoryValid(e,to)){const message=to==='chest'&&['fish','creature'].includes(e.kind)?'Catches belong in your bucket or cold storage.':['fridge','freezer'].includes(to)&&e.kind==='creature'&&!edibleCatch(e)?'Keep this little animal in your bucket, or put it back.':e.ref?.spoiled?'Spoiled catches cannot go into cold storage.':'This container is full for that item.';openInventory(inventoryMode,message);return;}if(to==='parcel'){const id=deliveryRequest,r=routine.post.requests.find(r=>r.id===id);modal('Seal this parcel?',`${inventoryArt(e)}<p>${htmlText(inventoryName(e))}</p><button id="sealParcel" class="action gold">Pack for the ferry</button><button id="cancelMove" class="action">Back</button>`,'MAILBOX OUTBOX');$('sealParcel').onclick=()=>{if(e.source!=='pack'&&!inventoryMove(e,'pack'))return openInventory('delivery','This item has already moved.');reserveParcel(id,requestInventory(r).indexOf(e.ref));openInventory('delivery');};$('cancelMove').onclick=()=>openInventory('delivery');return;}if(e.kind==='stock'&&e.count>1){modal('How many?',`${inventoryArt(e)}<p>${htmlText(inventoryName(e))}</p><div class="quantity-choice"><button id="moveOne" class="gold">One</button><button id="moveAll">All that fit</button></div><button id="cancelMove" class="action">Back</button>`,'MOVE ITEMS');$('moveOne').onclick=()=>{inventoryMove(e,to);openInventory(inventoryMode);};$('moveAll').onclick=()=>{inventoryMove(e,to,true);openInventory(inventoryMode);};$('cancelMove').onclick=()=>openInventory(inventoryMode);return;}inventoryMove(e,to);openInventory(inventoryMode);};
const inventoryView11=openInventory;openInventory=function(mode='bag',message=''){inventoryView11(mode,message);const panes=document.querySelector('.inventory-panes');if(!panes)return;const targets=[...(mode!=='bag'?[mode==='delivery'?'parcel':mode]:[]),'pack','buckets'];$('modalBody').insertAdjacentHTML('afterbegin',`<nav class="inventory-jumps" aria-label="Jump to container">${targets.map(s=>`<button id="jump-${s}" aria-label="${s==='pack'?'Backpack':s==='buckets'?'Buckets':s}">${s==='buckets'?artIcon('bucket'):uiIcon(s==='pack'?'bag':s==='parcel'?'mail':s==='chest'?'chest':'fridge')}</button>`).join('')}</nav>`);for(const s of targets)$('jump-'+s).onclick=()=>{const node=s==='buckets'?document.querySelector('.bucket-panel'):$('inventory-'+s)?.closest('.inventory-container');node?.scrollIntoView({behavior:'smooth',block:'start'});};};
openBag=message=>openInventory('bag',message);openFridge=message=>openInventory('fridge',message);openChest=message=>openInventory('chest',message);openDelivery=()=>{mailboxTab='outbox';openInventory('delivery');};
