const postDraw10=drawDockPost;drawDockPost=function(t){postDraw10(t);if(routine.post.requests.some(r=>r.status==='finding'&&requestCandidates(r).length)){ctx.save();ctx.translate(192,265);const pulse=settings.ambient?1+Math.sin(t*3)*.08:1;ctx.scale(pulse,pulse);ctx.fillStyle='#db654e';ctx.strokeStyle='#fff3c8';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#fff8db';ctx.font='900 28px IslandRound';ctx.textAlign='center';ctx.fillText('!',0,10);ctx.restore();}};
