const sleepUpdate10=updateSleep;updateSleep=function(dt){if(bedEntrance&&sleeping){sleeping.entry=(sleeping.entry||0)+dt;if(sleeping.entry<1.8)return;bedEntrance=null;$('sleepOverlay').classList.remove('hidden');}const was=!!sleeping;sleepUpdate10(dt);if(was&&!sleeping){wakeAnimation=2.8;houseMessage('A big yawn… a stretch… good morning.');}};
const lifeTick10=tickLife;tickLife=function(dt){if(wakeAnimation>0){wakeAnimation=Math.max(0,wakeAnimation-dt);if(!wakeAnimation){routine.room={x:327,y:326,dir:'down'};persist();}return true;}return lifeTick10(dt);};
