const foodIcon10=foodIcon;foodIcon=k=>k==='timber'?artIcon('wood'):foodIcon10(k);
let woodActive=false,woodLastSwing=-10;
function woodlandState(){return routine.woodland||={day:calendar().day,stage:0,hits:0,claimed:false};}
function openWoodcutting(){let w=woodlandState();if(w.day!==calendar().day)routine.woodland=w={day:calendar().day,stage:0,hits:0,claimed:false};woodActive=!w.claimed;modal(w.claimed?'Enough wood for today':w.stage?'Chop the fallen trunk':'A tree at the edge of the grove',`<canvas id="woodCanvas" width="400" height="300" aria-label="Woodcutting clearing"></canvas>${w.claimed?'<p>Fresh shoots and fallen branches will be worth checking tomorrow.</p>':'<div class="wood-timing"><i></i><b id="woodPointer"></b></div><button id="chopWood" class="action gold">Swing axe</button><p id="woodStatus" class="mini-note"></p>'}<button id="woodBack" class="action">Back to the shrine</button>`,'WOOD FOR LATER');if(!w.claimed)$('chopWood').onclick=chopWood;$('woodBack').onclick=()=>{woodActive=false;openWoods();};drawWoodcutting();}
function chopWood(){const w=woodlandState();if(!woodActive||w.claimed||clock-woodLastSwing<.32)return false;woodLastSwing=clock;const timing=(Math.sin(clock*2.2)+1)/2;w.hits+=timing>.3&&timing<.7?2:1;playFX('wood');if(w.hits>=(w.stage?6:5)){w.hits=0;if(!w.stage){w.stage=1;persist();openWoodcutting();return true;}w.claimed=true;woodActive=false;routine.chest.items.timber=(routine.chest.items.timber||0)+3;persist();openWoodcutting();notify('3 timber stored in your wooden chest.');return true;}persist();drawWoodcutting();return true;}
